class ApronBoyFace extends StatelessWidget {
  final ApronBoyFaceExpression expression;
  final double? width;
  final double? height;
  final ColorMapper? colorMapper;

  const ApronBoyFace({
    required this.expression,
    this.width,
    this.height,
    this.colorMapper,
    super.key,
  });

  @override
  Widget build(BuildContext context) {
    late String svgString;
    switch (expression) {
      case ApronBoyFaceExpression.talk:
        svgString = _boyFaceTalk;
      case ApronBoyFaceExpression.default_:
        svgString = _boyFaceDefault;
      case ApronBoyFaceExpression.smile:
